/* FONT FACE */
/* TT2020 default */
@font-face {
    font-family: "TT2020 Base";
    src: url(data:application/font-woff2;charset=utf-8;base64,) format('woff2');
    font-weight: normal;
    font-style: italic;

}

@font-face {
    font-family: "TT2020 Base";
    src: url(data:application/font-woff2;charset=utf-8;base64,) format('woff2');
    font-weight: normal;
    font-style: normal;
	font-display: swap;

}

@font-face { 
	font-family: "TT2020 Base";
	src: url(data:application/octet-stream;base64,);
	font-style: bold;
	font-weight: 700;
	font-display: swap; 

  }

  @font-face { 
	font-family: "TT2020 Base";
	src: url(data:application/octet-stream;base64,);
	font-style: italic;
	font-weight: bold;
	font-display: swap;
  }


/* rest */

.small-caps {
	font-variant-caps: small-caps
}
.normal {
	font-variant-caps: normal;
	font-style: italic;
}

body {
/* TYPOGRAPHY + FONTS */

	--font-general: "TT2020 Base";
	--font-interface-theme: var(--font-general);
	--font-text-theme: var(--font-general), var(--font-text-override);
	--font-monospace-theme: "TT2020 Base";

	--normal-weight: 500;
	--bold-weight: 620;
	--icon-muted: 0.5;
	--border-width: 1px;
	--border-width-alt: 1px;
}

/* source mode */
.markdown-source-view {
	font-family: var(--font-text-theme);
}

/* live preview */
.markdown-source-view.is-live-preview {
	font-family: var(--font-editor-theme);
}

/* reading mode */
.markdown-preview-view {
	font-family: var(--font-text-theme);
}

/* COLOR VARIABLES */
:root {
  --color-red-rgb: 255, 57, 77;
  --color-orange-rgb: 255, 84, 0;
  --color-yellow-rgb: 255, 215, 125;
  --color-yellow-light-rgb: 255, 229, 167;
  --color-green-rgb: 172, 224, 153;
  --color-cyan-rgb: 166, 230, 227;
  --color-blue-rgb: 83, 119, 145;
  --sandover-purple-rgb: 197, 133, 204;
  --color-salmon-rgb: 255, 134, 113;
  --color-salmon-lighter-rgb: 255, 169, 154;
  --color-red: #ff394d;
  --color-orange: #ff5400;
  --color-yellow: #ffd77d;
  --color-yellow-light: #ffe5a7;
  --color-green: #ace099;
  --color-cyan: #a6e6e3;
  --color-blue: #537791;
  --sandover-purple: #c585cc;
  --color-darker-purple: 153, 119, 181;
  --color-pink: #fc62a2;
  --color-salmon: #ff8671;
  --color-salmon-lighter: #ffa99a;
  --color-dark1-rgb: 40, 40, 40; 
  --color-dark1: #282828;
  --color-light1-rgb: 255, 252, 244;
  --color-light1: #fffcf4;
  --color-gray-rgb: 240, 240, 240;

}

body {

	/* square corners! */
	--radius-s: 0px;
	--radius-m: 0px;
	--radius-l: 0px;
	--input-radius: 0px;
	--tab-radius-active: 0px;
	--checkbox-radius: 0px;
	--toggle-radius: 0px;
	--toggle-thumb-radius: 0px;
	--slider-thumb-radius: 0px;

	/* headings */
	--h1-size: 1.5em;
  --h2-size: 1.4em;
  --h3-size: 1.3em;
  --h4-size: 1.1em;
  --h5-size: 1em;
  --h6-size: 0.85em;
  --h1-weight: 600;
  --h2-weight: 600;
  --h3-weight: 500;
  --h4-weight: 500;
  --h5-weight: 500;
  --h6-weight: 400;
  --h1-variant: normal;
  --h2-variant: normal;
  --h3-variant: normal;
  --h4-variant: normal;
  --h5-variant: normal;
  --h6-variant: normal;
  --h1-style: bold;
  --h2-style: normal;
  --h3-style: normal;
  --h4-style: normal;
  --h5-style: normal;
  --h6-style: normal;

    /* Line widths */
	--line-width: 40rem;
	--line-height: 1.5;
	--line-height-normal: var(--line-height);
	--max-width: 88%;
	--max-col-width: 18em;

	/* Icons */
	--icon-muted: 0.5;

	/* links */
	--link-decoration: none;
	--link-decoration-hover: underline;
	--link-external-decoration: none;

	/* tags */
    --tag-decoration:                 none;
    --tag-decoration-hover:           underline;
    --tag-padding-x:                  .5em;
    --tag-padding-y:                  .2em;
    --tag-radius:                     .3em;

	--tab-font-weight: 500;
	--bold-weight: 600;

	--checkbox-radius: 0;
	
  /* Mobile sidebars */
  --mobile-left-sidebar-width: 280pt;
  --mobile-right-sidebar-width: 240pt;
  --top-left-padding-y:0px;

	/* graph view */
	.graph-view.color-fill {
		color: var(--sandover-purple);

	  }
	  .graph-view.color-line {
		color: var(--color-yellow-light);
	  }
	  .graph-view.color-text {
		color: var(--color-dark1);
	  }
	  .graph-view.color-fill-highlight {
		color: var(--color-green);
	  }
	  .graph-view.color-line-highlight {
		color: var(--color-gray-rgb);
	  }


}

.HyperMD-list-line input[type="checkbox"],
.markdown-preview-view input[type="checkbox"] {
  box-sizing: border-box;
  /* (tweak): change text-normal to text-faint below to give unchecked checkboxes a lighter border */
  border: 1.5px solid var(--text-normal);
  position: relative;
  width: 12px;
  height: 12px;
  margin: 0;
  margin-right: 4px;
  margin-bottom: 0px;
  border-radius: 2px;
}


.theme-light {

	/* accents */
	--accent-h: 9;
	--accent-s: 89%;
	--accent-l: 66%;
	--interactive-accent: var(--color-accent);

	/* Background */
	--background-primary: var(--color-light1);
	--background-primary-alt: var(--color-light1);
	--background-secondary: var(--color-light1);

	/* Text colors */
	  --text-normal: #000000;
	  --text-muted: #000000;
	  --text-faint: #000000;
	  --link-color: var(--color-salmon);
	  --text-accent: var(--color-salmon);
	  --tag-color: var(--color-salmon);

	/* headings */
	  --h1-color: var(--sandover-purple);

	/* highlights */
	  --text-highlight-bg: var(--color-yellow-light);


	  --titlebar-text-color-focused: #000000;
	  --nav-item-color-hover: #000000;
	  --interactive-hover: rgba(var(--color-salmon), 0.5);
	  --interactive-accent-hover: var(--color-salmon);
	  --text-error: var(--color-red);
	  --blockquote-border-color: none;
	  --blockquote-color: var(--color-blue);
	  --indentation-guide-color: var(--color-base-25);
	  --indentation-guide-color-active: var(--sandover-purple);
	  --list-marker-color: #000000;

	  /* window */
	  --ribbon-background: var(--color-light1);
	  --ribbon-background-collapsed: var(--color-light1);
	  --titlebar-background: var(--color-salmon-lighter);
	  --titlebar-background-focused: var(--color-salmon-lighter);
	  --titlebar-text-color: #fffcf4;
	  --titlebar-text-color-focused: #000000;
	  --titlebar-text-weight: 300;
	  --status-bar-border-color: #141300;
	  --background-modifier-active-hover: var(--color-salmon-lighter);
	  --color-base-35: #fffcf4;


	  .workspace-ribbon {
		--icon-color-hover: var(--color-salmon);
	  }

	/* Navigation */
		--vault-name-font-weight: 700;
		--icon-color: #141300;
		--icon-color-active: #fffcf4;
		--icon-color-focused: #fffcf4;
		--icon-color-focused-active: #fffcf4;
		--icon-color-hover: #fffcf4;

	/* callouts */
	--callout-border-width: 1px;
    --callout-border-opacity: 0.4;
    --callout-default: var(--color-blue-rgb);
    --callout-note: var(--color-blue-rgb);
    --callout-summary: var(--color-cyan-rgb);
    --callout-info: var(--color-yellow-rgb);
    --callout-todo: var(--color-green-rgb);
    --callout-important: var(--sandover-purple-rgb);
    --callout-tip: var(--color-salmon-lighter-rgb);
    --callout-success: var(--color-red-rgb);
    --callout-question: var(--color-pink-rgb);
    --callout-warning: var(--color-orange-rgb);
    --callout-fail: var(--color-red-rgb);
    --callout-error: var(--color-red-rgb);
    --callout-bug: var(--color-red-rgb);
    --callout-example: var(--sandover-purple-rgb);
    --callout-quote: var(--color-green-rgb);

	.workspace-tab-header-container, .workspace-tab-container-before.is-before-active, .workspace-tab-container-after.is-after-active, .workspace-tab-header.is-before-active, .workspace-tab-header.is-after-active, .workspace-tab-container-before.is-before-active .workspace-tab-header-inner, .workspace-tab-container-after.is-after-active .workspace-tab-header-inner, .workspace-tab-header.is-before-active .workspace-tab-header-inner, .workspace-tab-header.is-after-active .workspace-tab-header-inner {

		background-color: var(--color-salmon-lighter);
	}

	.workspace-leaf {

		--icon-color-hover: var(--color-salmon);
	}

}

.theme-dark {
	/* color variables */
	--color-dark1-rgb: var(--color-dark1);
	--color-light1-rgb: var(--color-light1);

	/* background */
	--background-primary: var(--color-dark1-rgb);
	--background-secondary: var(--color-dark1-rgb);

	/* Text colors */
	--text-normal: var(--color-light1);
	--text-muted: rgba(var(--color-light1-rgb), 0.8);
	--text-faint: rgba(var(--color-light1-rgb), 0.5);
	--link-color: var(--color-salmon);

	--h1-color: var(--sandover-purple);

	--text-highlight-bg: rgba(var(--color-yellow-light-rgb), 0.3);

	--text-accent: var(--color-salmon);
	--tag-color: var(--color-salmon);

	--list-marker-color: var(--color-light1);

	--blockquote-border-color: none;
	--blockquote-color: var(--color-cyan);
	--indentation-guide-color: var(--color-base-25);
	--indentation-guide-color-active: var(--sandover-purple);

	/* WINDOW */
	--ribbon-background: rgba(var(--color-dark1-rgb), 0.5);
	--ribbon-background-collapsed:rgba(var(--color-dark1-rgb), 0.5);
	--titlebar-background: var(--color-salmon);
	--titlebar-background-focused: var(--color-salmon);
	--titlebar-text-color: #000000;
	--titlebar-text-color-focused: #000000;
	--titlebar-text-weight: 300;
	--status-bar-border-color: #141300;
	--background-modifier-active-hover: var(--color-salmon);
	--titlebar-text-color-focused: var(--color-light1);

	.workspace-tab-header-container, .workspace-tab-container-before.is-before-active, .workspace-tab-container-after.is-after-active, .workspace-tab-header.is-before-active, .workspace-tab-header.is-after-active, .workspace-tab-container-before.is-before-active .workspace-tab-header-inner, .workspace-tab-container-after.is-after-active .workspace-tab-header-inner, .workspace-tab-header.is-before-active .workspace-tab-header-inner, .workspace-tab-header.is-after-active .workspace-tab-header-inner {

		background-color: var(--color-salmon);
		
	}

	--nav-item-color-hover: var(--color-salmon);
	--nav-item-color-active: var(--color-light1);

	--tab-text-color-focused-active: var(--color-light1);
	--tab-text-color-focused-active-current: var(--color-light1);

	/* Navigation */
	--vault-name-font-weight: 700;
	--icon-color: var(--color-light1-rgb);
	--icon-color-active: var(--sandover-purple);
	--icon-color-focused: #fffcf4;
	--icon-color-focused-active: var(--sandover-purple-rgb);
	--icon-color-hover: #fffcf4;

/* callouts */
--callout-border-width: 1px;
    --callout-border-opacity: 0.4;
    --callout-default: var(--color-blue-rgb);
    --callout-note: var(--color-blue-rgb);
    --callout-summary: var(--color-cyan-rgb);
    --callout-info: var(--color-yellow-rgb);
    --callout-todo: var(--color-green-rgb);
    --callout-important: var(--sandover-purple-rgb);
    --callout-tip: var(--color-salmon-lighter-rgb);
    --callout-success: var(--color-red-rgb);
    --callout-question: var(--color-pink-rgb);
    --callout-warning: var(--color-orange-rgb);
    --callout-fail: var(--color-red-rgb);
    --callout-error: var(--color-red-rgb);
    --callout-bug: var(--color-red-rgb);
    --callout-example: var(--sandover-purple-rgb);
    --callout-quote: var(--color-green-rgb);

	/* graph view */
	.graph-view.color-text {
		color: var(--color-light1);
	}

	}

.theme-dark,
.theme-light {
  --accent-h: 9;
  --accent-s: 89%;
  --accent-l: 66%;

/* Code */
	--code-normal: var(--text-normal);
	--code-comment: var(--sandover-purple);
	--code-function: var(--color-cyan);
	--code-important: var(--color-orange);
	--code-keyword: var(--color-green);
	--code-operator: var(--code-normal);
	--code-property: var(--code-normal);
	--code-punctuation: var(--code-normal);
	--code-string: var(--color-cyan);
	--code-tag: var(--color-red);
	--code-value: var(--color-blue);
/* Tables */
	--table-header-size: inherit;
	--table-header-weight: var(--font-bold);
	--table-header-color: inherit;


/* Focus border */
	--background-modifier-border-focus: var(--interactive-accent);
  }

  .list-bullet:after {
	color: var(--list-marker-color);
	background-color: var(--list-marker-color);
  }

.workspace-tab-header.is-active::before, .workspace-tab-header.is-active::after {
	display: none;
}

svg * {
	stroke-linecap: square;
	stroke-linejoin: miter;

}

.menu {
	padding: var(--size-2-1);
}

.menu-item {
	padding: var(--size-4-1) var(--size-4-2);
}

.menu-separator {
	margin: var(--size-2-1) calc(var(--size-2-1) * -1);
}

body {
	/* canvas colors */
	--canvas-background: var(--background-primary);
	--canvas-color-1: var(--sandover-purple-rgb);
	--canvas-color-2: var(--color-orange-rgb);
	--canvas-color-3: var(--color-blue-rgb);
	--canvas-color-4: var(--color-red-rgb);
	--canvas-color-5: var(--color-yellow-rgb);
	--canvas-color-6: var(--color-green-rgb);
	--canvas-dot-pattern: var(--color-salmon-lighter);

}

.mod-canvas-color-2 {
	--canvas-orange: var(--color-orange-rgb);
}

body.is-mobile.theme-dark.mobile-black-background {
	--color-base-00: black;
  }



